<script>
    // Initial local storage hydration or fallbacks
    let roster = JSON.parse(localStorage.getItem('pickupRoster')) || [
        { id: 1, name: "Emily Davis", grade: "Kindergarten", contacts: "Mark Davis (Dad) 555-0143", notes: "No peanut products", status: "Waiting" },
        { id: 2, name: "Liam Johnson", grade: "3rd Grade", contacts: "Sarah J. (Mom) 555-0188", notes: "Goes to YMCA bus", status: "Picked Up" }
    ];

    function saveToLocalStorage() {
        localStorage.setItem('pickupRoster', JSON.stringify(roster));
    }

    function renderRoster() {
        const tbody = document.getElementById('rosterTableBody');
        tbody.innerHTML = '';

        if (roster.length === 0) {
            tbody.innerHTML = `<tr><td colspan="6" style="text-align: center; color: var(--text-muted); padding: 2rem;">No students on the roster.</td></tr>`;
            return;
        }

        roster.forEach(student => {
            const tr = document.createElement('tr');
            const statusClass = student.status === 'Picked Up' ? 'status-pickedup' : 'status-waiting';

            tr.innerHTML = `
                <td>
                    <span class="badge ${statusClass}" style="cursor: pointer;" onclick="toggleStatus(${student.id})">
