    function saveStudent(e) {
        e.preventDefault();
        const id = document.getElementById('studentId').value;
        const name = document.getElementById('studentName').value;
        const grade = document.getElementById('grade').value;
        const contacts = document.getElementById('contacts').value;
        const notes = document.getElementById('notes').value;
        const status = document.getElementById('status').value;

        if (id) {
            const index = roster.findIndex(s => s.id == id);
            if (index !== -1) roster[index] = { id: Number(id), name, grade, contacts, notes, status };
        } else {
            const newStudent = { id: Date.now(), name, grade, contacts, notes, status };
            roster.push(newStudent);
        }

        saveToLocalStorage();
        renderRoster();
        resetForm();
    }

    function editStudent(id) {
        const student = roster.find(s => s.id === id);
        if (!student) return;

        document.getElementById('studentId').value = student.id;
        document.getElementById('studentName').value = student.name;
        document.getElementById('grade').value = student.grade;
        document.getElementById('contacts').value = student.contacts;
        document.getElementById('notes').value = student.notes;
        document.getElementById('status').value = student.status;

        document.getElementById('formHeader').innerText = "Edit Student Profile";
        document.getElementById('cancelEditBtn').style.display = "inline-flex";
    }

    function deleteStudent(id) {
        if (confirm("Are you sure you want to remove this student from the active roster?")) {
            roster = roster.filter(s => s.id !== id);
            saveToLocalStorage();
            renderRoster();
            if (document.getElementById('studentId').value == id) resetForm();
        }
    }

    function toggleStatus(id) {
        const student = roster.find(s => s.id === id);
        if (student) {
            student.status = student.status === 'Waiting' ? 'Picked Up' : 'Waiting';
            saveToLocalStorage();
            renderRoster();
        }
    }

    function resetForm() {
        document.getElementById('rosterForm').reset();
        document.getElementById('studentId').value = '';
        document.getElementById('formHeader').innerText = "Add New Student";
        document.getElementById('cancelEditBtn').style.display = "none";
    }

    function copyHandoffList() {
        const waiting = roster.filter(s => s.status === 'Waiting');
        const pickedUp = roster.filter(s => s.status === 'Picked Up');

        let text = `AFTER-SCHOOL PICKUP HANDOFF LIST\n`;
        text += `Generated: ${new Date().toLocaleString()}\n`;
        text += `=========================================\n\n`;

        text += `STILL WAITING (${waiting.length}):\n`;
        if (waiting.length === 0) text += `- No students remaining -\n`;
        waiting.forEach(s => {
            text += `- ${s.name} (${s.grade})\n`;
            text += `  Pickups: ${s.contacts}\n`;
            if (s.notes) text += `  Notes: ${s.notes}\n`;
            text += '\n';
        });

        text += `ALREADY PICKED UP (${pickedUp.length}):\n`;
        if (pickedUp.length === 0) text += `- None -\n`;
        pickedUp.forEach(s => {
            text += `- ${s.name} (${s.grade})\n`;
        });

        navigator.clipboard.writeText(text).then(() => {
            const toast = document.getElementById('toast');
            toast.style.display = 'block';
            setTimeout(() => toast.style.display = 'none', 3000);
        });
    }

    function escapeHtml(str) {
        if (!str) return '';
        return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
    }

    window.addEventListener("DOMContentLoaded", renderRoster);
</script>
